body:
Requests using composite aggs with `afterKey` set to a missing field end up throwing an exception due to what looks like incorrect mapping.

And two entries inside "index-a" and no entries in "index-b":

```
POST index-a/_doc
{
  "bool" : true
}

POST index-a/_doc
{
  "bool" : false
}

POST index-b/_doc
{}
```
which results in the following mappings:

```
{
  "index-b" : {
    "mappings" : { }
  },
  "index-a" : {
    "mappings" : {
      "properties" : {
        "bool" : {
          "type" : "boolean"
        }
      }
    }
  }
}
```

Run a composite agg against it:
```
POST index-*/_search
{
  "size" : 0,
  "_source" : false,
  "aggregations" : {
    "groupby" : {
      "composite" : {
        "size" : 1,
        "sources" : [
          {
            "agg" : {
              "terms" : {
                "field" : "bool",
                "missing_bucket" : true,
                "order" : "asc"
              }
            }
          }
        ]
        ,"after": {"agg" : false}
      }
    }
  }
}
```

This works and should return something like:

```
{
  "took" : 0,
  "timed_out" : false,
  "_shards" : {
    "total" : 2,
    "successful" : 2,
    "skipped" : 0,
    "failed" : 0
  },
  "hits" : {
    "total" : {
      "value" : 2,
      "relation" : "eq"
    },
    "max_score" : null,
    "hits" : [ ]
  },
  "aggregations" : {
    "groupby" : {
      "after_key" : {
        "agg" : false
      },
      "buckets" : [
        {
          "key" : {
            "agg" : false
          },
          "doc_count" : 1
        }
      ]
    }
  }
}
```

Ask for the next composite agg page:
```
{
  "size" : 0,
  "_source" : false,
  "aggregations" : {
    "groupby" : {
      "composite" : {
        "size" : 1,
        "sources" : [
          {
            "agg" : {
              "terms" : {
                "field" : "bool",
                "missing_bucket" : true,
                "order" : "asc"
              }
            }
          }
        ],
        "after": {"agg" : false}
      }
    }
  }
}
```

this results in:
```
{
  "took" : 0,
  "timed_out" : false,
  "_shards" : {
    "total" : 2,
    "successful" : 1,
    "skipped" : 0,
    "failed" : 1,
    "failures" : [
      {
        "shard" : 0,
        "index" : "index-b",
        "node" : "_ropmc3_StufvH-TmSMSPQ",
        "reason" : {
          "type" : "illegal_argument_exception",
          "reason" : "invalid value, expected string, got Boolean"
        }
      }
    ]
  },
  ...
```

